{
  "implementation": "import math

def solve(case):
    sentence_vectors = case['sentence_vectors']
    query_vector = case['query_vector']
    context_weight = case['context_weight']

    n = len(sentence_vectors)
    if n == 0:
        return {'ranking': [], 'scores': []}

    # compute mean of sentence vectors
    dim = len(query_vector)
    mean = [0.0] * dim
    for vec in sentence_vectors:
        for i, v in enumerate(vec):
            mean[i] += v
    for i in range(dim):
        mean[i] /= n

    # compute adapted query: (1 - w) * query + w * mean
    adapted = [(1 - context_weight) * q + context_weight * m for q, m in zip(query_vector, mean)]

    # compute norm of adapted query
    norm_adapted = math.sqrt(sum(x * x for x in adapted))

    # compute cosine similarity for each sentence
    scores = []
    for vec in sentence_vectors:
        dot = sum(a * b for a, b in zip(adapted, vec))
        norm_vec = math.sqrt(sum(v * v for v in vec))
        if norm_adapted == 0.0 or norm_vec == 0.0:
            sim = 0.0
        else:
            sim = dot / (norm_adapted * norm_vec)
        scores.append(sim)

    # derive ranking (indices sorted by score descending)
    ranking = sorted(range(n), key=lambda i: scores[i], reverse=True)
    sorted_scores = [scores[i] for i in ranking]

    return {'ranking': ranking, 'scores': sorted_scores}"
}
